import {FILES_API,MAX_FILE_MB} from '../config.js';
import {uid,esc,money,dateText,daysLeft,today,num,icon,downCsv} from './utils.js';
import {start,state,isDemo,signIn,register,resetPassword,verifyAgain,refreshUser,logout,canEdit,isAdmin,upsertVehicle,deleteVehicle,upsertRecord,removeRecord,updateUser,replaceAttachment,retryTrash,allData} from './store.js';
import {uploadFile,fetchFile,downloadAttachment,compressImage,prepareVehiclePhoto,deleteFile} from './files.js';
const root=document.getElementById('app'),toastBox=document.getElementById('toast');
let page='dashboard',selectedVehicle=null,detailTab='anagrafica',expenseFilter='all',docFilter='all',bellOpen=false,loginMode='login',activeModal=null,searchFiles=[],photoPicked=null,working=false,thumbCache=new Map(),fileUrls=[];
let mobileMenuOpen=false;

const carName=v=>`${v?.brand||''} ${v?.model||''}`.trim()||'Automobile';
const carById=id=>state.vehicles.find(v=>v.id===id);
const docs=id=>state.documents[id]||[];
const jobs=id=>(state.maintenance[id]||[]).slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
const expenses=id=>(state.expenses[id]||[]).slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
const carImage=v=>v?.photo?.fileId?`<img class="real" data-photo="${esc(v.id)}" src="/assets/vehicles/racecar.svg" alt="Foto ${esc(carName(v))}"/>`:`<img src="/assets/vehicles/racecar.svg" alt="Illustrazione sportiva del veicolo"/>`;
const mIcon=(name,n=18)=>icon(name,n);
const amountItem=x=>num(x.cost??x.amount);
const allExpenses=()=>state.vehicles.flatMap(v=>[...expenses(v.id).map(x=>({...x,vehicleId:v.id,vehicle:v,source:'Spesa',amount:num(x.amount)})),...jobs(v.id).filter(x=>num(x.cost)>0).map(x=>({...x,vehicleId:v.id,vehicle:v,source:'Manutenzione',category:x.type||'Manutenzione',amount:num(x.cost),description:x.description||x.type}))]).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
function deadlines(){const out=[];
 for(const v of state.vehicles){
  for(const d of docs(v.id)){if(d.expiry)out.push({vehicle:v,source:'Documento',name:d.title||d.category||'Documento',date:d.expiry,id:d.id});}
  for(const j of jobs(v.id)){if(j.nextDate)out.push({vehicle:v,source:'Manutenzione',name:'Prossimo '+(j.type||'intervento'),date:j.nextDate,id:j.id});}
  for(const [key,label] of [['inspectionDue','Revisione'],['taxDue','Bollo'],['warrantyDue','Garanzia']] ){if(v[key])out.push({vehicle:v,source:'Auto',name:label,date:v[key],id:v.id});}
 }
 return out.sort((a,b)=>String(a.date).localeCompare(String(b.date)));
}
const imminent=()=>deadlines().filter(x=>daysLeft(x.date)<=30);
const deadlinePill=d=>{const n=daysLeft(d);return n==null?'<span class="rl-pill">Non indicata</span>':n<0?'<span class="rl-pill bad">SCADUTA</span>':n<=30?`<span class="rl-pill warn">${n} GIORNI</span>`:'<span class="rl-pill good">REGOLARE</span>';};
function toast(message,error=false){toastBox.textContent=message;toastBox.className='show '+(error?'error':'success');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastBox.className='',5400);}
function syncMobileMenu(){
 const mobile=window.matchMedia('(max-width:820px)').matches;
 const open=mobile&&mobileMenuOpen;
 document.documentElement.classList.toggle('rl-mobile-menu-open',open);
 const toggle=root.querySelector('.rl-mobile-toggle'), side=root.querySelector('#redline-mobile-menu');
 if(toggle){toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Chiudi il menu':'Apri il menu');}
 if(side){side.inert=mobile&&!open;side.setAttribute('aria-hidden',String(mobile&&!open));}
}
function setMobileMenu(open,focusToggle=false){
 mobileMenuOpen=window.matchMedia('(max-width:820px)').matches&&!!open;
 syncMobileMenu();
 if(mobileMenuOpen){root.querySelector('.rl-mobile-close')?.focus({preventScroll:true});}
 else if(focusToggle){root.querySelector('.rl-mobile-toggle')?.focus({preventScroll:true});}
}
function navigate(p,vid,tab){setMobileMenu(false);page=p;if(vid)selectedVehicle=vid;if(tab)detailTab=tab;bellOpen=false;render();window.scrollTo({top:0,behavior:'smooth'});} 
function humanBytes(n){if(!n)return '0 MB';return (n<1048576?(n/1024).toFixed(0)+' KB':(n/1048576).toFixed(1)+' MB');}
const filesTotal=()=>Object.values(state.documents).flat().concat(Object.values(state.maintenance).flat(),Object.values(state.expenses).flat(),state.vehicles.map(v=>({attachment:v.photo}))).reduce((s,x)=>s+num(x.attachment?.size),0);
function downloadJSON(){const blob=new Blob([JSON.stringify(allData(),null,2)],{type:'application/json'});saveBlob(blob,`REDLINE-dati-${today()}.json`);}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function styleText(){return `<div class="track-atmosphere" aria-hidden="true">
 <div class="track-chequer"></div><div class="track-pit-line"></div>
 <svg class="track-plan" viewBox="0 0 700 600" role="presentation" xmlns="http://www.w3.org/2000/svg">
  <defs><linearGradient id="courseMetal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#bdc6d2" stop-opacity=".65"/><stop offset="1" stop-color="#697785" stop-opacity=".1"/></linearGradient><filter id="glowred"><feGaussianBlur stdDeviation="6"/></filter></defs>
  <g transform="rotate(-12 350 310)">
  <path d="M248 36 C300 6 416 49 430 107 C441 154 375 195 402 227 C432 269 566 190 597 242 C631 301 561 378 503 396 C446 414 418 382 379 426 C333 487 300 534 225 514 C169 497 161 451 195 398 C237 326 163 294 113 281 C62 266 54 202 87 165 C125 124 167 161 192 112 C207 84 217 52 248 36 Z" fill="none" stroke="#19232d" stroke-width="58" opacity=".8" stroke-linecap="round" stroke-linejoin="round"/>
  <path d="M248 36 C300 6 416 49 430 107 C441 154 375 195 402 227 C432 269 566 190 597 242 C631 301 561 378 503 396 C446 414 418 382 379 426 C333 487 300 534 225 514 C169 497 161 451 195 398 C237 326 163 294 113 281 C62 266 54 202 87 165 C125 124 167 161 192 112 C207 84 217 52 248 36 Z" fill="none" stroke="url(#courseMetal)" stroke-width="3.3" opacity=".68"/>
  <path d="M248 36 C300 6 416 49 430 107 C441 154 375 195 402 227 C432 269 566 190 597 242 C631 301 561 378 503 396 C446 414 418 382 379 426 C333 487 300 534 225 514 C169 497 161 451 195 398 C237 326 163 294 113 281 C62 266 54 202 87 165 C125 124 167 161 192 112 C207 84 217 52 248 36 Z" fill="none" stroke="#ff493a" stroke-width="7" opacity=".22" filter="url(#glowred)"/>
  <path d="M248 36 C300 6 416 49 430 107 C441 154 375 195 402 227 C432 269 566 190 597 242 C631 301 561 378 503 396 C446 414 418 382 379 426 C333 487 300 534 225 514 C169 497 161 451 195 398 C237 326 163 294 113 281 C62 266 54 202 87 165 C125 124 167 161 192 112 C207 84 217 52 248 36 Z" fill="none" stroke="#ff493a" stroke-width="2.2" opacity=".73" stroke-dasharray="14 18"/>
  <path d="M248 36 C300 6 416 49 430 107 C441 154 375 195 402 227 C432 269 566 190 597 242 C631 301 561 378 503 396 C446 414 418 382 379 426 C333 487 300 534 225 514 C169 497 161 451 195 398 C237 326 163 294 113 281 C62 266 54 202 87 165 C125 124 167 161 192 112 C207 84 217 52 248 36 Z" fill="none" stroke="#dce3eb" stroke-width="2" opacity=".22" stroke-dasharray="2 24"/>
  <path d="M222 58 l-22 -15" stroke="#ff493a" stroke-width="7"/><circle cx="222" cy="58" r="5" fill="#ff493a"/>
  </g>
  <path d="M68 538 h106 m-106 0 v-9 m106 9 v9" stroke="#ba4140" opacity=".4"/><text x="70" y="564" font-family="Arial,sans-serif" fill="#bbc2cc" opacity=".56" font-size="12" letter-spacing="3">RACING CIRCUIT / 01</text>
  <text x="523" y="86" font-family="Arial,sans-serif" fill="#ff493a" opacity=".66" font-size="11" letter-spacing="2">TRACK MAP</text>
 </svg>
</div>`;}
function renderAuth(){if(!state.user){root.innerHTML=`<div class="rl-auth"><section class="rl-auth-art"><div><img src="/assets/icons/redline-racing.svg" width="72" height="72" alt="Racing"/><h1>REDLINE<span class="rl-red">.</span></h1><div class="rl-eyebrow">PRIVATE MOTOR ARCHIVE</div><p class="rl-small">EVERY CAR. EVERY DETAIL.</p><img class="bigcar" src="/assets/vehicles/racecar.svg" alt="Automobile sportiva"/></div></section><section class="rl-auth-panel"><div class="rl-eyebrow">ACCESSO RISERVATO / 01</div><h2>${loginMode==='register'?'REGISTRATI':loginMode==='reset'?'RECUPERA PASSWORD':'BENTORNATO IN GARAGE'}</h2><p class="rl-small">Accesso con email e password. La sessione rimane attiva sul dispositivo finché non effettui la disconnessione.</p><form id="auth-form">${loginMode==='register'?field('Nome','name','text',null,'Il tuo nome'):''}${field('Email','email','email',null,'nome@esempio.it',true)}${loginMode!=='reset'?field('Password','password','password',null,'Minimo 6 caratteri',true):''}<button class="rl-btn" type="submit">${loginMode==='register'?'CREA ACCOUNT':loginMode==='reset'?'INVIA EMAIL':'ACCEDI'} ${mIcon('arrow',16)}</button></form><div class="rl-flex"><button class="textlike" data-act="auth-mode" data-mode="login">Accedi</button><button class="textlike" data-act="auth-mode" data-mode="register">Registrati</button><button class="textlike" data-act="auth-mode" data-mode="reset">Password dimenticata?</button></div></section></div>`;return;}
 if(!state.user.emailVerified){root.innerHTML=`<div class="rl-auth"><section class="rl-auth-art"><div><img width="72" src="/assets/icons/redline-racing.svg"/><h1>REDLINE<span class="rl-red">.</span></h1><p>PRIVATE MOTOR ARCHIVE</p></div></section><section class="rl-auth-panel"><h2>VERIFICA L'EMAIL</h2><p class="rl-small">Abbiamo inviato un link all'indirizzo <b>${esc(state.user.email)}</b>. Apri l'email, conferma e poi premi il pulsante qui sotto.</p><div class="rl-flex" style="margin-top:20px"><button class="rl-btn" data-act="verified">HO VERIFICATO L'EMAIL</button><button class="rl-btn secondary" data-act="resend">RINVIA EMAIL</button><button class="rl-btn secondary" data-act="logout">ESCI</button></div></section></div>`;return;}
 if(!state.profile||state.profile.status!=='approved'){const rejected=state.profile?.status==='rejected';root.innerHTML=`<div class="rl-auth"><section class="rl-auth-art"><div><img width="72" src="/assets/icons/redline-racing.svg"/><h1>REDLINE<span class="rl-red">.</span></h1><p>PRIVATE MOTOR ARCHIVE</p></div></section><section class="rl-auth-panel"><div class="rl-eyebrow">AUTORIZZAZIONI / 02</div><h2>${rejected?'ACCESSO NON AUTORIZZATO':'APPROVAZIONE IN ATTESA'}</h2><p class="rl-small">La tua email è stata verificata. ${rejected?'L’amministratore ha rifiutato o sospeso l’accesso.':'L’amministratore deve approvare il tuo account prima di visualizzare le auto.'}</p><p class="rl-small">Account: ${esc(state.user.email)}</p><div style="margin-top:22px"><button class="rl-btn secondary" data-act="logout">ESCI</button></div></section></div>`;return;}
}
function field(label,name,type='text',value='',placeholder='',required=false,extra=''){
 const val=value==null?'':value;return `<div class="rl-field ${extra}"><label for="f-${name}">${esc(label)}</label><input class="rl-input" id="f-${name}" name="${esc(name)}" type="${type}" ${required?'required':''} placeholder="${esc(placeholder)}" value="${esc(val)}" ${type==='number'?'min="0" step="any"':''}/></div>`;
}
function textarea(label,name,value='',extra='full'){return `<div class="rl-field ${extra}"><label for="f-${name}">${esc(label)}</label><textarea class="rl-textarea" id="f-${name}" name="${esc(name)}">${esc(value)}</textarea></div>`;}
function selectField(label,name,options,value,extra=''){return `<div class="rl-field ${extra}"><label for="f-${name}">${esc(label)}</label><select class="rl-select" name="${esc(name)}" id="f-${name}">${options.map(o=>{const v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;}
function navButton(name,label,ico){return `<button class="navitem ${page===name?'active':''}" data-act="navigate" data-page="${name}" title="${label}"><span class="navicon">${mIcon(ico,19)}</span><span class="navtext">${label}</span><span class="navsel"></span></button>`;}
function shell(){const user=state.profile||{},alerts=imminent();const pageNames={dashboard:'PANORAMICA',garage:'IL MIO GARAGE',fascicolo:'FASCICOLO',documents:'DOCUMENTI',maintenance:'MANUTENZIONE',deadlines:'SCADENZE',expenses:'SPESE',admin:'AMMINISTRATORE'};
 return `<button type="button" class="rl-mobile-backdrop" data-act="close-menu" aria-label="Chiudi il menu laterale" tabindex="-1"></button><aside class="side" id="redline-mobile-menu" aria-label="Menu di navigazione"><div class="rl-brand"><img class="rl-brand-icon" src="/assets/icons/redline-racing.svg" alt="Racing"/><div><div class="rl-brand-name">REDLINE</div><div class="rl-brand-sub">PRIVATE MOTOR ARCHIVE</div></div></div><button type="button" class="rl-mobile-close" data-act="close-menu" aria-label="Chiudi menu">${mIcon('close',19)}<span>CHIUDI MENU</span></button><div class="rl-nav-sect">CONTROLLO / GARAGE</div><nav class="navlist" aria-label="Navigazione principale">${navButton('dashboard','Panoramica','dashboard')}${navButton('garage','Il mio garage','garage')}${navButton('documents','Documenti','documents')}${navButton('maintenance','Manutenzione','maintenance')}${navButton('deadlines','Scadenze','deadlines')}${navButton('expenses','Spese','expenses')}</nav><div class="sidebar-bottom"><div class="modeblock"><span class="statuslight"></span><div><b>SISTEMA REDLINE</b><small>${isDemo?'Modalità demo':state.profile.role.toUpperCase()+' · accesso attivo'}</small></div></div>${isAdmin()?`<button class="adminlink" data-act="navigate" data-page="admin">${mIcon('admin')}<span>AMMINISTRAZIONE</span></button>`:''}<button class="adminlink" data-act="logout" title="Disconnetti">${mIcon('logout')}<span>DISCONNETTI</span></button></div></aside>
 <div class="wrap">${styleText()}<header class="topbar"><button type="button" class="rl-mobile-toggle" data-act="toggle-menu" aria-controls="redline-mobile-menu" aria-label="Apri il menu" aria-expanded="false"><span class="rl-hamburger" aria-hidden="true"><i></i><i></i><i></i></span><span>MENU</span></button><div class="crumbs"><span class="hide-small">REDLINE / GARAGE / </span><b>${pageNames[page]||'REDLINE'}</b></div><div class="topright"><span class="previewbadge">${isDemo?'DEMO LOCALE':(FILES_API?'LIVE · CLOUD':'ARCHIVIO FILE DA CONFIGURARE')}</span><button class="iconbutton" data-act="bell" title="Avvisi" aria-label="Apri avvisi">${mIcon('bell',21)}${alerts.length?'<span class="smallred"></span>':''}</button><div class="rl-avatar" title="${esc(state.user?.email||'Utente')}">${esc((user.name||state.user?.email||'R').charAt(0).toUpperCase())}</div></div></header>${bellOpen?alertPopover(alerts):''}<main class="content">${isDemo?'<div class="rl-notice" style="margin-bottom:16px">MODALITÀ DEMO: dati fittizi modificabili sul dispositivo. Il database e gli allegati online saranno attivi dopo la configurazione descritta nella guida.</div>':''}${renderPage()}</main></div>`;
}
function alertPopover(alerts){return `<div class="rl-alerts" role="dialog" aria-label="Avvisi"><div class="rl-spread"><h3>SCADENZE IN ARRIVO</h3><button class="rl-btn secondary slim" data-act="bell">${mIcon('close',14)}</button></div>${alerts.length?alerts.slice(0,10).map(x=>`<button class="rl-due ${daysLeft(x.date)<0?'overdue':'soon'}" style="width:100%;text-align:left;cursor:pointer" data-act="navigate" data-page="deadlines"><div><h3>${esc(x.name)}</h3><p>${esc(carName(x.vehicle))} · ${dateText(x.date)}</p></div>${deadlinePill(x.date)}</button>`).join(''):'<p class="rl-small">Nessuna scadenza entro 30 giorni.</p>'}<button class="rl-btn secondary slim" data-act="navigate" data-page="deadlines" style="margin-top:10px">TUTTE LE SCADENZE ${mIcon('arrow',14)}</button></div>`;}
function renderPage(){switch(page){case 'dashboard':return dashboard();case 'garage':return garage();case 'fascicolo':return fascicolo();case 'documents':return documentPage();case 'maintenance':return maintenancePage();case 'deadlines':return deadlinePage();case 'expenses':return expensePage();case 'admin':return adminPage();default:return dashboard();}}
function hgroup(kicker,title,desc,button=''){return `<div class="rl-hgroup"><div><div class="rl-eyebrow">${kicker}</div><h1>${title}</h1>${desc?`<p class="rl-small" style="margin-top:8px">${desc}</p>`:''}</div>${button}</div>`;}
const button=(text,act,args={},secondary=false)=>`<button class="rl-btn ${secondary?'secondary':''}" data-act="${act}" ${Object.entries(args).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${text}</button>`;
function dashboard(){const total=state.vehicles.length,all=allExpenses(),due=imminent(),featured=state.vehicles[0];return `${hgroup('CONTROL CENTER / 001','IL TUO <span class="rl-red">GARAGE.</span>','La tua collezione, ogni dettaglio sotto controllo.',canEdit()?button('AGGIUNGI AUTO '+mIcon('plus',16),'new-vehicle'):'')}
 ${featured?`<div class="rl-hero"><div class="rl-hero-ring" aria-hidden="true"></div><div class="rl-hero-big-number" aria-hidden="true">01</div><div class="rl-hero-content"><div class="rl-eyebrow">IN EVIDENZA / REDLINE GARAGE</div><div class="rl-hero-name">${esc(featured.brand||'AUTO')}<br/><span class="rl-red">${esc(featured.model||'')}</span></div><div class="rl-small">${esc(featured.trim||featured.fuel||'')} · ${esc(featured.year||'')}</div><span class="rl-plate">${esc(featured.plate||'SENZA TARGA')}</span><div class="rl-flex" style="margin-top:auto">${button('APRI FASCICOLO '+mIcon('arrow',15),'open-car',{id:featured.id})}${button('TUTTE LE AUTO','navigate',{page:'garage'},true)}</div></div><div class="rl-hero-car">${carImage(featured)}</div></div>`:`<div class="rl-hero"><div class="rl-hero-ring" aria-hidden="true"></div><div class="rl-hero-big-number" aria-hidden="true">00</div><div class="rl-hero-content"><div class="rl-eyebrow">IL TUO GARAGE È PRONTO</div><div class="rl-hero-name">REDLINE<span class="rl-red">.</span></div><p class="rl-small">Inizia inserendo la prima automobile.</p>${canEdit()?button('INSERISCI LA PRIMA AUTO','new-vehicle'):''}</div><div class="rl-hero-car"><img src="/assets/vehicles/racecar.svg" alt="Concept automobile"/></div></div>`}
 <div class="rl-hero-data"><div><span>VEICOLI IN GARAGE</span><b>${total}</b></div><div><span>DOCUMENTI ARCHIVIATI</span><b>${Object.values(state.documents).flat().length}</b></div><div><span>AVVISI ENTRO 30 GIORNI</span><b style="color:${due.length?'#ff6a64':''}">${due.length}</b></div><div><span>SPESE REGISTRATE</span><b>${money(all.reduce((s,x)=>s+x.amount,0))}</b></div></div>
 <div class="rl-columns" style="margin-top:20px"><section class="rl-card"><div class="rl-spread"><h2 class="rl-title">LE TUE AUTOMOBILI</h2>${button('VEDI GARAGE','navigate',{page:'garage'},true)}</div><div class="rl-line"></div><div class="rl-list">${state.vehicles.length?state.vehicles.slice(0,5).map(v=>`<button class="rl-row" data-act="open-car" data-id="${esc(v.id)}" style="color:inherit;text-align:left;cursor:pointer;width:100%"><div style="width:70px"><img width="70" src="/assets/vehicles/racecar.svg"/></div><div class="rl-row-main"><h3>${esc(carName(v))}</h3><p>${esc(v.trim||'')} · ${esc(v.plate||'')}</p></div>${mIcon('chevron',19)}</button>`).join(''):'<p class="rl-small">Nessuna automobile inserita.</p>'}</div></section><section class="rl-card"><div class="rl-spread"><h2 class="rl-title">ALERT & SCADENZE</h2>${button('VEDI TUTTE','navigate',{page:'deadlines'},true)}</div><div class="rl-line"></div><div class="rl-list">${due.length?due.slice(0,5).map(x=>`<div class="rl-due ${daysLeft(x.date)<0?'overdue':'soon'}"><div><h3>${esc(x.name)}</h3><p>${esc(carName(x.vehicle))} · ${dateText(x.date)}</p></div>${deadlinePill(x.date)}</div>`).join(''):'<p class="rl-small">Non risultano scadenze imminenti. Aggiungi date ai documenti per attivare gli avvisi.</p>'}</div></section></div>`;}
function garage(){return `${hgroup('FLEET OVERVIEW / 002','IL MIO <span class="rl-red">GARAGE.</span>','Tutti i veicoli, riconoscibili per marca, modello, targa e fotografia.',canEdit()?button('NUOVA AUTOMOBILE '+mIcon('plus',16),'new-vehicle'):'')}<div class="rl-grid">${state.vehicles.map((v,i)=>`<button class="rl-garage-card" data-act="open-car" data-id="${esc(v.id)}" style="text-align:left;color:inherit"><div class="rl-carflag">AUTO ${String(i+1).padStart(2,'0')}</div><div class="rl-carimg" data-number="${String(i+1).padStart(2,'0')}">${carImage(v)}</div><div class="rl-garage-info"><div class="rl-mini">${esc(v.trim||v.fuel||'')}</div><h2>${esc(carName(v).toUpperCase())}</h2><div class="rl-spread"><span class="rl-plate">${esc(v.plate||'SENZA TARGA')}</span><span class="rl-small">${esc(v.year||'')} · ${Number(v.mileage||0).toLocaleString('it-IT')} km</span></div></div></button>`).join('')||'<div class="rl-empty"><h3>GARAGE VUOTO</h3>Inserisci la tua prima automobile.</div>'}</div>`;}
function attr(k,v){return `<div class="rl-doc-detail"><span>${esc(k)}</span><b>${esc(v??'—')}</b></div>`;}
function fascicolo(){let v=carById(selectedVehicle)||state.vehicles[0];if(!v)return garage();selectedVehicle=v.id;const tabs=[['anagrafica','SCHEDA TECNICA'],['documenti','DOCUMENTI'],['manutenzione','MANUTENZIONE'],['scadenze','SCADENZE'],['spese','SPESE']];return `${hgroup('FASCICOLO AUTOMOBILISTICO / '+esc(v.plate||''),esc(carName(v).toUpperCase()),`${esc(v.trim||'')} · ${esc(v.year||'')}`,`<div class="rl-flex">${button('ESPORTA FASCICOLO PDF','print-report',{id:v.id},true)}${canEdit()?button('MODIFICA AUTO '+mIcon('edit',15),'edit-vehicle',{id:v.id},true):''}</div>`)}
 <div class="rl-hero"><div class="rl-hero-ring" aria-hidden="true"></div><div class="rl-hero-big-number" aria-hidden="true">${String(state.vehicles.findIndex(x=>x.id===v.id)+1).padStart(2,'0')}</div><div class="rl-hero-content"><div class="rl-eyebrow">SCHEDA VEICOLO / ${esc(v.plate||'')}</div><div class="rl-hero-name">${esc(v.brand||'')}<br/><span class="rl-red">${esc(v.model||'')}</span></div><span class="rl-plate">${esc(v.plate||'SENZA TARGA')}</span><div class="rl-small">${esc(v.trim||v.fuel||'')} · ${esc(v.year||'')}</div></div><div class="rl-hero-car">${carImage(v)}</div></div><div class="rl-tabstrip">${tabs.map(([t,label])=>`<button class="rl-tab ${detailTab===t?'active':''}" data-act="car-tab" data-tab="${t}">${label}</button>`).join('')}</div>
 ${detailTab==='anagrafica'?technical(v):detailTab==='documenti'?documentList(v.id):detailTab==='manutenzione'?maintenanceList(v.id):detailTab==='scadenze'?deadlineList(v.id):expenseList(v.id)}`;}
function technical(v){const facts=[['Targa',v.plate],['Marca',v.brand],['Modello',v.model],['Allestimento',v.trim],['Anno immatricolazione',v.year],['Data prima immatricolazione',dateText(v.registrationDate)],['Telaio (VIN)',v.vin],['Alimentazione',v.fuel],['Cilindrata',v.displacement?`${v.displacement} cm³`:null],['Potenza',v.power],['Colore',v.color],['Chilometraggio',`${Number(v.mileage||0).toLocaleString('it-IT')} km`],['Intestatario',v.holder],['Proprietario',v.owner],['Acquisto',dateText(v.purchaseDate)],['Prezzo d’acquisto',v.purchasePrice?money(v.purchasePrice):'—'],['Garanzia',dateText(v.warrantyDue)],['Autore/fonte della foto',v.photoCredit],['Licenza foto',v.photoLicense],['Fonte web foto',v.photoSource],['Note',v.notes]];return `<div class="rl-columns"><section class="rl-card"><div class="rl-spread"><h2 class="rl-title">IDENTIFICAZIONE VEICOLO</h2>${canEdit()?button('AGGIORNA CHILOMETRAGGIO','mileage',{id:v.id},true):''}</div><div class="rl-line"></div><div class="rl-form-grid">${facts.map(([k,x])=>`<div class="rl-card rl-nopadding" style="padding:12px!important"><div class="rl-mini">${esc(k.toUpperCase())}</div><b style="font-size:12px;display:block;margin-top:7px;overflow-wrap:anywhere">${esc(x||'—')}</b></div>`).join('')}</div></section><section class="rl-card"><h2 class="rl-title">FASCICOLO DEL VEICOLO</h2><div class="rl-line"></div><p class="rl-small">Ogni documento, intervento e spesa è associato esclusivamente a questa automobile.</p><div class="rl-list" style="margin-top:18px">${[['documenti','DOCUMENTI',docs(v.id).length],['manutenzione','INTERVENTI',jobs(v.id).length],['spese','REGISTRAZIONI SPESA',expenses(v.id).length+jobs(v.id).length]].map(([tab,label,n])=>`<button class="rl-row" data-act="car-tab" data-tab="${tab}" style="width:100%;color:#fff;cursor:pointer"><div class="rl-row-main"><h3>${label}</h3><p>${n} registrazioni</p></div>${mIcon('chevron',18)}</button>`).join('')}</div>${canEdit()?`<div class="rl-line"></div>${button('ELIMINA AUTOMOBILE','delete-car',{id:v.id},true)}`:''}</section></div>`;}
const docCategories=['Libretto / Documento Unico','Assicurazione RCA','Bollo','Revisione','Certificato di proprietà','Contratto di acquisto','Garanzia','Certificato di assicurazione','Certificato revisione','Multa / Verbale','Documento di identità','Altro'];
const jobTypes=['Tagliando','Cambio olio','Filtri','Pneumatici','Freni','Batteria','Revisione','Carrozzeria','Riparazione meccanica','Distribuzione','Climatizzazione','Altro'];
const costTypes=['Carburante','Assicurazione RCA','Bollo','Pedaggi','Parcheggio','Lavaggio','Pneumatici','Manutenzione extra','Riparazione','Multa','Acquisto','Altro'];
function vehicleFilters(selected='all',kind='docs'){return `<div class="rl-filter">${[['all','TUTTE LE AUTO'],...state.vehicles.map(v=>[v.id,carName(v)])].map(([id,label])=>`<button class="rl-chip ${selected===id?'selected':''}" data-act="filter-${kind}" data-id="${esc(id)}">${esc(label)}</button>`).join('')}</div>`;}
function documentPage(){return `${hgroup('DOCUMENT CENTER / 003','ARCHIVIO <span class="rl-red">DOCUMENTI.</span>','Polizze, libretto, revisioni e qualsiasi altro file, direttamente nel fascicolo del veicolo.',canEdit()&&state.vehicles.length?button('AGGIUNGI DOCUMENTO '+mIcon('plus',16),'new-doc'): '')}${vehicleFilters(docFilter,'docs')}${documentList(docFilter)}`;}
function documentList(carId){const cars=carId==='all'?state.vehicles:[carById(carId)].filter(Boolean);
 const list=cars.flatMap(v=>docs(v.id).map(d=>({...d,vehicle:v}))).sort((a,b)=>String(b.expiry||b.dateStart||b.updatedAt||'').localeCompare(String(a.expiry||a.dateStart||a.updatedAt||'')));
 return `<div class="rl-flex" style="margin-bottom:14px"><span class="rl-mini">${list.length} DOCUMENTI</span><span class="rl-mini">${list.filter(d=>d.attachment?.fileId).length} CON ALLEGATO</span><span class="rl-mini">${humanBytes(list.reduce((s,d)=>s+num(d.attachment?.size),0))} TOTALI</span></div><div class="rl-docs">${list.length?list.map(d=>docCard(d)).join(''):`<div class="rl-empty" style="grid-column:1/-1"><h3>NESSUN DOCUMENTO</h3>Premi “Aggiungi documento” per registrare una nuova polizza, un libretto o un altro allegato.</div>`}</div>`;}
function docCard(d){const file=d.attachment?.fileId,code=d.vehicle?.id||'',can=canEdit();const thumb=`<button class="rl-doc-thumb" data-act="preview" data-kind="documents" data-vid="${esc(code)}" data-id="${esc(d.id)}" ${!file?'disabled':''} title="${file?'Apri allegato':'Nessun allegato'}">${file?`<div class="rl-paper"><div>${esc(d.category||'DOCUMENTO')}</div><small></small><small></small><small></small><small></small></div><img data-thumb="${esc(code)}|${esc(d.id)}" alt="Anteprima documento" style="display:none;position:absolute;inset:0"/>`:`<div class="rl-paper"><div>${esc(d.category||'DOCUMENTO')}</div><small></small><small></small><small></small><small></small></div>`}</button>`;
 return `<article class="rl-doc-card">${thumb}<div class="rl-doc-body"><div class="rl-mini">${esc(d.vehicle?carName(d.vehicle):'AUTO')} · ${esc(d.vehicle?.plate||'')}</div><h3>${esc(d.title||d.category||'Documento')}</h3><div>${deadlinePill(d.expiry)}</div>${attr('Categoria',d.category)}${d.issuer?attr('Ente/compagnia',d.issuer):''}${d.policy?attr('N. polizza/pratica',d.policy):''}${d.expiry?attr('Scadenza',dateText(d.expiry)):''}<p style="overflow-wrap:anywhere">${file?'ALLEGATO: '+esc(d.attachment.originalName||'PDF/immagine'):'Nessun file allegato'}</p><div class="rl-doc-actions">${file?`<button data-act="preview" data-kind="documents" data-vid="${esc(code)}" data-id="${esc(d.id)}">APRI FILE</button><button data-act="download-file" data-kind="documents" data-vid="${esc(code)}" data-id="${esc(d.id)}">SCARICA</button>`:''}${can?`<button data-act="edit-doc" data-vid="${esc(code)}" data-id="${esc(d.id)}">${file?'MODIFICA / SOSTITUISCI':'MODIFICA / ALLEGA'}</button><button data-act="delete-record" data-kind="documents" data-vid="${esc(code)}" data-id="${esc(d.id)}">ELIMINA</button>`:''}</div></div></article>`;}
function maintenancePage(){return `${hgroup('SERVICE HISTORY / 004','MANUTENZIONE <span class="rl-red">AUTO.</span>','Cronologia degli interventi: i più recenti sono sempre in alto.',canEdit()&&state.vehicles.length?button('NUOVO INTERVENTO '+mIcon('plus',16),'new-job'):'')}${vehicleFilters(docFilter,'docs')}${maintenanceList(docFilter)}`;}
function maintenanceList(carId){const cars=carId==='all'?state.vehicles:[carById(carId)].filter(Boolean),list=cars.flatMap(v=>jobs(v.id).map(j=>({...j,vehicle:v}))).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 return `<div class="rl-card"><div class="rl-spread"><h2 class="rl-title">STORICO INTERVENTI</h2><span class="rl-mini">ORDINE: PIÙ RECENTI PRIMA</span></div><div class="rl-line"></div><div class="rl-list">${list.length?list.map(j=>`<article class="rl-row"><div style="text-align:center;min-width:62px"><div class="rl-mini">${esc(dateText(j.date))}</div><div class="rl-red">${mIcon('maintenance',24)}</div></div><div class="rl-row-main"><h3>${esc(j.type||'Intervento')}</h3><p>${esc(carName(j.vehicle))} · ${esc(j.vehicle?.plate||'')} · ${num(j.mileage).toLocaleString('it-IT')} km</p><p>${esc(j.description||'')}${j.workshop?' · '+esc(j.workshop):''}</p>${j.nextDate?`<p class="rl-red">Prossimo intervento: ${dateText(j.nextDate)}</p>`:''}</div><div class="rl-cost">${money(j.cost)}</div>${j.attachment?.fileId?`<button class="rl-btn secondary slim" data-act="preview" data-kind="maintenance" data-vid="${esc(j.vehicle.id)}" data-id="${esc(j.id)}">${mIcon('file',16)}</button>`:''}${canEdit()?`<button class="rl-btn secondary slim" data-act="edit-job" data-vid="${esc(j.vehicle.id)}" data-id="${esc(j.id)}">${mIcon('edit',16)}</button><button class="rl-btn secondary slim" data-act="delete-record" data-kind="maintenance" data-vid="${esc(j.vehicle.id)}" data-id="${esc(j.id)}">${mIcon('trash',15)}</button>`:''}</article>`).join(''):'<div class="rl-empty"><h3>NESSUN INTERVENTO</h3>Registra il primo tagliando, cambio gomme o riparazione.</div>'}</div></div>`;}
function deadlinePage(){return `${hgroup('EXPIRATION RADAR / 005','LE TUE <span class="rl-red">SCADENZE.</span>','Polizze, bollo, revisione, garanzia e manutenzioni programmate.')}${vehicleFilters(docFilter,'docs')}${deadlineList(docFilter)}`;}
function deadlineList(carId){const list=deadlines().filter(x=>carId==='all'||x.vehicle.id===carId);const due=list.filter(x=>daysLeft(x.date)<=30).length,over=list.filter(x=>daysLeft(x.date)<0).length;
 return `<div class="rl-grid" style="margin-bottom:20px"><div class="rl-overview-card"><small>SCADENZE TOTALI</small><strong>${list.length}</strong></div><div class="rl-overview-card"><small>ENTRO 30 GIORNI</small><strong style="color:#ffbe7f">${due}</strong></div><div class="rl-overview-card"><small>SCADUTE</small><strong style="color:#ff7074">${over}</strong></div></div><div class="rl-duegrid">${list.length?list.map(x=>`<div class="rl-due ${daysLeft(x.date)<0?'overdue':daysLeft(x.date)<=30?'soon':''}"><div><div class="rl-mini">${esc(x.source.toUpperCase())} · ${esc(x.vehicle.plate||'')}</div><h3>${esc(x.name)}</h3><p>${esc(carName(x.vehicle))} · ${dateText(x.date)}</p></div><div style="text-align:right">${deadlinePill(x.date)}<div style="margin-top:9px" class="rl-count">${daysLeft(x.date)<0?'!':daysLeft(x.date)+'g'}</div></div></div>`).join(''):'<div class="rl-empty"><h3>NESSUNA SCADENZA</h3>Imposta le date nei documenti e nelle schede dei veicoli.</div>'}</div>`;}
function expensePage(){return `${hgroup('COST CONTROL / 006','SPESE <span class="rl-red">AUTOMOBILI.</span>','Spese filtrabili per veicolo, comprensive dei costi manutenzione.')}${vehicleFilters(expenseFilter,'expenses')}${expenseList(expenseFilter)}`;}
function expenseList(carId){const list=allExpenses().filter(x=>carId==='all'||x.vehicleId===carId),total=list.reduce((s,x)=>s+x.amount,0);const sums={};list.forEach(x=>{const cat=x.source==='Manutenzione'?'Manutenzione':x.category||'Altro';sums[cat]=(sums[cat]||0)+x.amount;});const palette=['#f44c4b','#f3a26c','#72bfd9','#b895db','#79c5aa','#e4d47f'];
 return `<div class="rl-columns" style="margin-bottom:20px"><div class="rl-card accentleft"><div class="rl-mini">TOTALE SPESE SELEZIONATE</div><div class="rl-amount">${money(total)}</div><p class="rl-small">${list.length} movimenti · include automaticamente gli importi degli interventi.</p><div class="rl-pie">${Object.entries(sums).map(([k,v],i)=>`<span style="width:${total?100*v/total:0}%;background:${palette[i%palette.length]}" title="${esc(k)}"></span>`).join('')}</div><div class="rl-flex">${Object.entries(sums).map(([k,v],i)=>`<span class="rl-mini"><b style="color:${palette[i%palette.length]}">●</b> ${esc(k)} ${money(v)}</span>`).join('')}</div></div><div class="rl-card"><h2 class="rl-title">PER AUTOMOBILE</h2><div class="rl-line"></div>${state.vehicles.map(v=>{const n=allExpenses().filter(x=>x.vehicleId===v.id).reduce((s,x)=>s+x.amount,0);return `<button class="rl-row" data-act="filter-expenses" data-id="${esc(v.id)}" style="cursor:pointer;width:100%;color:inherit;text-align:left"><div class="rl-row-main"><h3>${esc(carName(v))}</h3><p>${esc(v.plate||'')}</p></div><b>${money(n)}</b></button>`}).join('')||'<p class="rl-small">Nessuna automobile.</p>'}</div></div><div class="rl-card"><div class="rl-spread"><h2 class="rl-title">REGISTRO SPESE</h2>${canEdit()?button('AGGIUNGI SPESA','new-expense') :''}</div><div class="rl-line"></div><div class="rl-list">${list.length?list.map(x=>`<div class="rl-row"><div class="rl-red">${mIcon('expenses',21)}</div><div class="rl-row-main"><h3>${esc(x.description||x.category||'Spesa')}</h3><p>${esc(carName(x.vehicle))} · ${esc(x.category||x.source)} · ${dateText(x.date)} · ${esc(x.source)}</p></div><div class="rl-cost">${money(x.amount)}</div>${x.source!=='Manutenzione'&&canEdit()?`<button class="rl-btn secondary slim" data-act="edit-expense" data-vid="${esc(x.vehicleId)}" data-id="${esc(x.id)}">${mIcon('edit',15)}</button><button class="rl-btn secondary slim" data-act="delete-record" data-kind="expenses" data-vid="${esc(x.vehicleId)}" data-id="${esc(x.id)}">${mIcon('trash',15)}</button>`:''}</div>`).join(''):'<div class="rl-empty"><h3>NESSUNA SPESA</h3>Aggiungi una spesa manuale oppure un intervento con costo.</div>'}</div>${list.length?`<div class="rl-flex" style="margin-top:18px">${button('ESPORTA CSV SPESE','csv-expenses',{},true)}</div>`:''}</div>`;}
function adminPage(){if(!isAdmin())return '<div class="rl-notice">Accesso riservato all’amministratore.</div>';const users=state.users.length?state.users:[{id:state.user.uid,email:state.user.email,name:state.profile.name,role:'admin',status:'approved'}];return `${hgroup('ACCESS MANAGEMENT / 007','PANNELLO <span class="rl-red">ADMIN.</span>','Approva, sospendi e gestisci i permessi degli utenti.')}
 <div class="rl-columns"><div class="rl-card"><h2 class="rl-title">UTENTI REGISTRATI</h2><div class="rl-line"></div><div style="overflow:auto"><table class="rl-admin-table"><thead><tr><th>UTENTE</th><th>RUOLO</th><th>STATO</th><th>AZIONE</th></tr></thead><tbody>${users.map(u=>`<tr><td><b>${esc(u.name||'Utente')}</b><br/><span class="rl-small">${esc(u.email||'')}</span></td><td><select id="role-${esc(u.id)}" ${u.id===state.user.uid?'disabled':''}><option value="viewer" ${u.role==='viewer'?'selected':''}>Sola lettura</option><option value="editor" ${u.role==='editor'?'selected':''}>Modifica</option><option value="admin" ${u.role==='admin'?'selected':''}>Admin</option></select></td><td><select id="status-${esc(u.id)}" ${u.id===state.user.uid?'disabled':''}><option value="pending" ${u.status==='pending'?'selected':''}>In attesa</option><option value="approved" ${u.status==='approved'?'selected':''}>Approvato</option><option value="rejected" ${u.status==='rejected'?'selected':''}>Revocato</option></select></td><td>${u.id===state.user.uid?'<span class="rl-pill good">TU</span>':button('SALVA','save-user',{id:u.id},true)}</td></tr>`).join('')}</tbody></table></div></div><div class="rl-card"><h2 class="rl-title">SICUREZZA & ARCHIVIO</h2><div class="rl-line"></div><p class="rl-small">Il database è indipendente dalle altre app Firebase. Tutti i documenti sono custoditi in un bucket privato e richiedono autenticazione e approvazione.</p><div class="rl-line"></div><div class="rl-mini">STIMA DOCUMENTI ATTIVI</div><div class="rl-amount">${humanBytes(filesTotal())}</div><p class="rl-small">Stima ricavata dagli allegati presenti nelle schede (non include eventuali file orfani).</p><div class="rl-line"></div><button class="rl-btn secondary" data-act="retry-cleanup">RIPROVA CANCELLAZIONI PENDENTI</button><div class="rl-line"></div><button class="rl-btn secondary" data-act="export-json">ESPORTA BACKUP DATI JSON</button><p class="rl-small" style="margin-top:10px">Il backup JSON contiene i dati, non i PDF. Per gli allegati utilizza il backup per veicolo.</p><div style="margin-top:12px"><button class="rl-btn secondary" data-act="export-attachments">BACKUP AUTO CON ALLEGATI (ZIP)</button></div></div></div>`;}
function render(){if(state.loading){root.innerHTML='<div class="splash"><img src="/assets/icons/redline-racing.svg"/><h1>REDLINE</h1><p>CONNESSIONE AL GARAGE…</p></div>';return;}
 if(!isDemo&&(!state.user||!state.user.emailVerified||state.profile?.status!=='approved')){renderAuth();return;}
 root.innerHTML=shell();syncMobileMenu();loadImages();}
function vehicleOptions(value){return state.vehicles.map(v=>`<option value="${esc(v.id)}" ${value===v.id?'selected':''}>${esc(carName(v))} · ${esc(v.plate||'')}</option>`).join('');}
function vehicleField(value){return `<div class="rl-field"><label>AUTOMOBILE</label><select class="rl-select" name="vehicleId" required>${vehicleOptions(value||selectedVehicle||state.vehicles[0]?.id)}</select></div>`;}
function fileZone(existing=null){return `<div class="rl-field full"><label>${existing?.fileId?'Sostituisci l’allegato (qualsiasi documento)':'Allega PDF o fotografia (facoltativo)'}</label><div class="rl-filezone"><div class="rl-red">${mIcon('upload',24)}</div><input name="attachment" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,.heic,.heif,application/pdf,image/*"/><div class="rl-small">PDF, JPG, PNG, WebP o HEIC · massimo ${MAX_FILE_MB} MB per file</div>${existing?.fileId?`<div class="rl-attach-warn">Allegato attuale: ${esc(existing.originalName||'documento')}. Se scegli un nuovo file, il vecchio verrà eliminato dall’archivio <b>dopo</b> il salvataggio riuscito.</div>`:''}<div id="extract-status" class="rl-small"></div></div></div>`;}
function openModal(html,wide=false){closeModal();const div=document.createElement('div');div.className='rl-modal-back';div.id='redline-modal';div.innerHTML=`<div class="rl-modal ${wide?'wide':''}" role="dialog" aria-modal="true"><button class="rl-modal-close" data-act="close-modal" title="Chiudi">${mIcon('close')}</button>${html}</div>`;document.body.appendChild(div);div.addEventListener('click',e=>{if(e.target===div)closeModal()});activeModal=div;}
function closeModal(){activeModal?.remove();activeModal=null;photoPicked=null;searchFiles=[];}
