async function pdfEngine(){if(window.__redlinePdf)return window.__redlinePdf;const p=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');p.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';window.__redlinePdf=p;return p;}
async function ocrEngine(){if(window.Tesseract)return window.Tesseract;
 await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';s.onload=resolve;s.onerror=reject;document.head.appendChild(s);});return window.Tesseract;}
function parseDocumentText(raw){const text=String(raw||'').replace(/\s+/g,' '),out={};if(text.length<8)return out;
 const dateMatches=[...text.matchAll(/\b([0-3]?\d)[\/.\-]([01]?\d)[\/.\-](20\d\d|19\d\d)\b/g)].map(x=>{const d=Number(x[1]),m=Number(x[2]),y=Number(x[3]);return d<=31&&m<=12?`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`:null}).filter(Boolean);
 const expiry=text.match(/(?:scadenza|valida fino|termine copertura|data fine)[\s:\-]*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]20\d\d)/i);if(expiry){const mm=expiry[1].match(/(\d{1,2}).(\d{1,2}).(\d{4})/);if(mm)out.expiry=`${mm[3]}-${mm[2].padStart(2,'0')}-${mm[1].padStart(2,'0')}`;}
 if(!out.expiry&&dateMatches.length>=2)out.expiry=dateMatches[dateMatches.length-1];
 if(dateMatches.length)out.dateStart=dateMatches[0];
 for(const name of ['Allianz','Generali','Unipol','Zurich','AXA','Vittoria Assicurazioni','Reale Mutua','Linear','Prima Assicurazioni','Genertel','Quixa','Verti','Sara Assicurazioni','Groupama']){if(text.toLowerCase().includes(name.toLowerCase())){out.issuer=name;break;}}
 const pol=text.match(/(?:numero\s+(?:di\s+)?polizza|n[°º.]\s*polizza|polizza\s+n[°º.]?)\s*[:#\-]?\s*([A-Z0-9\-/]{5,25})/i);if(pol)out.policy=pol[1];
 return out;
}
async function extractText(file){let raw='';if(file.type==='application/pdf'){
 const pdfjs=await pdfEngine();const bytes=new Uint8Array(await file.arrayBuffer());const pdf=await pdfjs.getDocument({data:bytes}).promise;
 for(let i=1;i<=Math.min(pdf.numPages,3);i++){const p=await pdf.getPage(i);const t=await p.getTextContent();raw+=' '+t.items.map(z=>z.str).join(' ');}
 if(raw.replace(/\s/g,'').length<16){const p=await pdf.getPage(1),viewport=p.getViewport({scale:1.5});const cv=document.createElement('canvas');cv.width=viewport.width;cv.height=viewport.height;await p.render({canvasContext:cv.getContext('2d'),viewport}).promise;const ocr=await ocrEngine();const r=await ocr.recognize(cv,'ita+eng');raw=r.data.text||'';}
 }else if(file.type.startsWith('image/')){const ocr=await ocrEngine();const r=await ocr.recognize(file,'ita+eng');raw=r.data.text||'';}
 return parseDocumentText(raw);
}
async function buildPreview(blob){if(blob.type==='application/pdf'){
 try{const pdfjs=await pdfEngine();const pdf=await pdfjs.getDocument({data:new Uint8Array(await blob.arrayBuffer())}).promise,p=await pdf.getPage(1),vp=p.getViewport({scale:0.42}),canvas=document.createElement('canvas');canvas.width=vp.width;canvas.height=vp.height;await p.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;return canvas.toDataURL('image/jpeg',.72);}catch(e){console.warn('PDF preview not available',e);return null;}
 }return URL.createObjectURL(blob);
}
